package com.ankit.joblens.batchapi;
import com.ankit.joblens.profile.ResumeProfileService; import org.springframework.http.MediaType; import org.springframework.web.bind.annotation.*; import org.springframework.web.multipart.MultipartFile; import java.util.List;
@RestController @RequestMapping("/api/candidate-profile") public class ResumeProfileController { private final ResumeProfileService service; public ResumeProfileController(ResumeProfileService service){this.service=service;} @GetMapping public Object profile(){return service.profile();} @PutMapping public Object update(@RequestBody SkillsRequest request){return service.updateSkills(request.skills());} @PostMapping(value="/resume",consumes=MediaType.MULTIPART_FORM_DATA_VALUE) public Object upload(@RequestPart("file") MultipartFile file)throws Exception{return service.readAndApply(file);} public record SkillsRequest(List<String> skills){} }
